`timescale 1 ps / 1 ps

module TOP_TB ();

	reg clk, rst;
	reg reset_write, reset_reset;
	reg [4:0] burstcount;
	reg write;
	reg [31:0] writedata;
	reg read;

	wire waitrequest_write;
	wire [63:0] readdata;
	wire waitrequest_read;

	parameter Default = 5'b00000, Init = 5'b00001, Test = 5'b00010, Done = 5'b01111;
	reg [4:0] Present_state = Default;

	TOP dut (
		.clk(clk),
		.reset({31'b0, rst}),
		.reset_write(reset_write),
		.reset_reset(reset_reset),
		.burstcount(burstcount),
		.waitrequest_write(waitrequest_write),
		.write(write),
		.writedata(writedata),
		.readdata(readdata),
		.read(read)
	);

	initial begin
		clk = 0;
		forever #10 clk = ~clk;
	end

	always @(posedge clk) begin
		case (Present_state)
			Default : Present_state <= Init;
			Init    : Present_state <= Test;
			Test    : Present_state <= Test;
			Done    : Present_state <= Done;
			default : Present_state <= Default;
		endcase
	end

	initial begin
		read = 1'b1;
	end

	task write_word;
		input [31:0] data_word;
		begin
			@(posedge clk);
			while (waitrequest_write) begin
				write <= 1'b0;
				writedata <= 32'h00000000;
				@(posedge clk);
			end

			write <= 1'b1;
			writedata <= data_word;
			@(posedge clk);

			write <= 1'b0;
			writedata <= 32'h00000000;
		end
	endtask

	always @(posedge clk) begin
		if (read && !waitrequest_read) begin
			$display("T=%0t OUTPUT = %h", $time, readdata);
		end
	end

	initial begin
		rst = 1'b0;
		reset_write = 1'b0;
		reset_reset = 1'b0;
		burstcount = 5'd1;
		write = 1'b0;
		writedata = 32'h00000000;

		#5;
		rst = 1'b1;
		reset_write = 1'b1;
		reset_reset = 1'b1;
		#20;
		rst = 1'b0;
